function AnalysisVisual({result}){const state=result.min<0?'risk':result.min<500?'caution':'healthy';const lowestDate=new Date(Date.UTC(2026,10,7+result.low.day)).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});return <div className="visual-analysis"><div className="analysis-heading"><h4>Your decision, explained</h4><span className={'status-pill '+state}>{state==='healthy'?'✓ Buffer preserved':state==='caution'?'! Low buffer':'! Shortfall'}</span></div><div className="impact-flow"><div><span>Starting balance</span><strong>{usd(result.selected.balance)}</strong></div><ArrowRight size={18}/><div><span>Purchase impact</span><strong>−{usd(result.price)}</strong></div><ArrowRight size={18}/><div><span>Lowest balance</span><strong>{usd(result.min)}</strong><small>{lowestDate}</small></div></div><div className={'buffer-visual '+state}><div><span>$500 safety buffer</span><strong>{result.min>=500?usd(result.min-500)+' above buffer':usd(500-result.min)+' below buffer'}</strong></div><div className="buffer-meter"><i style={{width:Math.max(2,Math.min(100,result.min/1500*100))+'%'}}/></div></div><div className="assumption-chips"><span>↓ Income: {usd(result.income)} × 4</span><span>↑ Bills: {usd(result.bills)} × 2</span><span>↑ Spending: {usd(result.daily)} / day</span>{result.stress>0&&<span>! Nov 28 expense: {usd(result.stress)}</span>}</div><div className="next-action"><Sparkles size={19}/><div><strong>{state==='healthy'?'Review with your household':state==='caution'?'Keep more breathing room':'Adjust before committing'}</strong><p>{state==='healthy'?'The modeled account stays above the buffer. Confirm bills and income before approving.':state==='caution'?'Try a lower price or a later date, then compare the forecast again.':'Try reducing the price, changing the date, or choosing another authorized account.'}</p></div></div><details className="model-details"><summary>See assumptions and limitations</summary><p>Income occurs Nov 15, Nov 30, Dec 15, and Dec 30. Bills occur Nov 15 and Dec 15. Daily variable spending is deducted throughout. The optional shock expense is applied Nov 28 to both scenarios. This synthetic 60-day model excludes interest, taxes, and unlisted expenses. Cash coverage does not determine whether a purchase is personally worthwhile.</p></details></div>}
