function FamilyCashflow({personal,cash}){const [view,setView]=useState('Balance');const daily=personal?18:50,income=personal?2600:5800,bills=personal?530:2180;let balance=cash;const rows=Array.from({length:61},(_,day)=>{if(day){balance-=daily;if([8,23,38,53].includes(day))balance+=income;if([8,38].includes(day))balance-=bills}return {day,base:balance,balance}});const totalIncome=income*4,totalOut=bills*2+daily*60;return <section className="family-cashflow"><div className="cashflow-heading"><div><span className="eyebrow">FINANCIAL OUTLOOK</span><h3>{personal?'Your':'Household'} 60-day cash flow</h3><p>Scheduled income, bills, and spending across included liquid accounts.</p></div><div className="cashflow-tabs">{['Balance','Money in / out'].map(t=><button key={t} className={view===t?'selected':''} onClick={()=>setView(t)}>{t}</button>)}</div></div>{view==='Balance'?<ForecastLines rows={rows}/>:<div className="inout-chart">{[['Income',totalIncome,'income'],['Bills',bills*2,'bills'],['Variable spending',daily*60,'spending']].map(([label,v,c])=><div key={label}><span>{label}</span><div><i className={c} style={{width:Math.max(2,v/Math.max(totalIncome,totalOut)*100)+'%'}}/></div><strong>{usd(v)}</strong></div>)}<div className="cashflow-net"><span>Net projected change</span><strong>{usd(totalIncome-totalOut)}</strong></div></div>}<div className="forecast-source"><span>RULE-BASED DEMO MODEL</span><p>Income: {usd(income)} on Nov 15, Nov 30, Dec 15, and Dec 30. Bills: {usd(bills)} on Nov 15 and Dec 15. Variable spending: {usd(daily)}/day. No interest, taxes, or unexpected expenses. Household totals can hide individual-account shortfalls.</p><small>Nemotron analysis is planned; no AI analysis is currently connected.</small></div></section>}
