function CombinedTransactions({personal}){const {member,ready,online}=useHousehold();const [names]=useStored('kt-account-names-v1',{});const [query,setQuery]=useState(''),[owner,setOwner]=useState('All'),[accountId,setAccountId]=useState('All'),[direction,setDirection]=useState('All');const accounts=online&&ready?visibleAccounts(financialAccounts,member,personal):[];const owners=[...new Set(accounts.map(a=>a.owner))];const rows=accounts.flatMap(a=>demoTransactions(a).map(t=>({...t,account:a}))).filter(t=>(owner==='All'||t.account.owner===owner)&&(accountId==='All'||t.account.id===accountId)&&(direction==='All'||(direction==='Credits'?t.amount>0:t.amount<0))&&(t.description+' '+t.category+' '+(names[t.account.id]||t.account.name)+' '+t.account.owner).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id));if(!member||!online||!ready)return <div className="account-access-empty"><ShieldCheck size={30}/><h3>Join your household to view transactions</h3><p>Only accounts permitted by your server membership are included.</p></div>;return <section className="combined-transactions"><div className="scope-banner"><ShieldCheck size={17}/>{personal||!isHouseholdHead(member)?'Showing only '+member.displayName+'’s accounts and transactions.':'Household-head view: transactions across all family accounts.'}</div><div className="transaction-section-heading"><div><h2>{personal?'Your transactions':'Family transactions'}</h2><p>See which account each transaction belongs to and who owns it.</p></div><span className="demo-tag">ILLUSTRATIVE HISTORY</span></div><div className="transaction-notice"><ShieldCheck size={16}/><span>These records are synthetic, not bank-connected. “Account owner” identifies ownership; it does not verify who initiated the transaction. Joint-account initiators are not available.</span></div><div className="transaction-toolbar combined-toolbar"><label>Search<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Merchant, account, or owner"/></label><label>Account owner<select value={owner} onChange={e=>setOwner(e.target.value)}><option>All</option>{owners.map(o=><option key={o}>{o}</option>)}</select></label><label>Account<select value={accountId} onChange={e=>setAccountId(e.target.value)}><option value="All">All accounts</option>{accounts.map(a=><option key={a.id} value={a.id}>{names[a.id]||a.name}</option>)}</select></label><label>Type<select value={direction} onChange={e=>setDirection(e.target.value)}><option>All</option><option>Credits</option><option>Debits</option></select></label><span>{rows.length} transactions</span></div><div className="transaction-table-wrap"><table className="transaction-table combined-table"><thead><tr><th>Date</th><th>Description</th><th>Account owner</th><th>Account</th><th>Category</th><th>Amount</th></tr></thead><tbody>{rows.map(t=><tr key={t.id}><td>{t.date}</td><td>{t.description}</td><td><span className={'transaction-owner '+(t.account.owner===member.displayName?'mine':'')}>{t.account.owner==='Joint'?'Priya + Sam':t.account.owner}{t.account.owner===member.displayName?' · You':''}</span></td><td>{names[t.account.id]||t.account.name}<small>{t.account.bank} · •••• {t.account.last4}</small></td><td>{t.category}</td><td className={t.amount>0?'txn-credit':'txn-debit'}>{t.amount>0?'+':'−'}{new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Math.abs(t.amount))}</td></tr>)}</tbody></table>{!rows.length&&<p className="txn-empty">No transactions match these filters.</p>}</div></section>}
